const revokeMCPOAuthClient = `-- name: RevokeMCPOAuthClient :exec
WITH c AS (
    UPDATE mcp_oauth_clients SET revoked_at = COALESCE(revoked_at, NOW())
    WHERE mcp_oauth_clients.client_id = $1
    RETURNING client_id
), g AS (
    UPDATE mcp_oauth_grants SET revoked_at = NOW()
    WHERE mcp_oauth_grants.client_id = $1 AND revoked_at IS NULL
), r AS (
    DELETE FROM mcp_oauth_auth_requests WHERE mcp_oauth_auth_requests.client_id = $1
), d AS (
    DELETE FROM mcp_oauth_codes WHERE mcp_oauth_codes.client_id = $1 AND used_at IS NULL
)
UPDATE mcp_oauth_tokens SET revoked_at = NOW()
WHERE mcp_oauth_tokens.client_id = $1 AND revoked_at IS NULL
`

// Blocks the client and everything issued to it: grants, tokens, pending
// requests and unused codes.
func (q *Queries) RevokeMCPOAuthClient(ctx context.Context, clientID string) error {
	_, err := q.db.Exec(ctx, revokeMCPOAuthClient, clientID)
	return err
}

const revokeMCPOAuthFamily = `-- name: RevokeMCPOAuthFamily :exec
UPDATE mcp_oauth_tokens SET revoked_at = NOW() WHERE family = $1 AND revoked_at IS NULL
`

func (q *Queries) RevokeMCPOAuthFamily(ctx context.Context, family uuid.UUID) error {
	_, err := q.db.Exec(ctx, revokeMCPOAuthFamily, family)
	return err
}

const revokeMCPOAuthGrant = `-- name: RevokeMCPOAuthGrant :one
UPDATE mcp_oauth_grants g
SET revoked_at = NOW()
FROM mcp_oauth_clients c
WHERE g.uuid = $1
  AND g.user_id = $2
  AND g.revoked_at IS NULL AND c.client_id = g.client_id
RETURNING g.id, g.uuid, g.client_id, c.client_name, g.resource, g.organization_id
`

type RevokeMCPOAuthGrantParams struct {
	Uuid   uuid.UUID   `json:"uuid"`
	UserID pgtype.Int8 `json:"user_id"`
}

type RevokeMCPOAuthGrantRow struct {
	ID             int64       `json:"id"`
	Uuid           uuid.UUID   `json:"uuid"`
	ClientID       string      `json:"client_id"`
	ClientName     string      `json:"client_name"`
	Resource       string      `json:"resource"`
	OrganizationID pgtype.Int8 `json:"organization_id"`
}

// Disconnects one of the subject's apps; no row when missing, foreign or
// already revoked.
func (q *Queries) RevokeMCPOAuthGrant(ctx context.Context, arg RevokeMCPOAuthGrantParams) (RevokeMCPOAuthGrantRow, error) {
	row := q.db.QueryRow(ctx, revokeMCPOAuthGrant, arg.Uuid, arg.UserID)
	var i RevokeMCPOAuthGrantRow
	err := row.Scan(
		&i.ID,
		&i.Uuid,
		&i.ClientID,
		&i.ClientName,
		&i.Resource,
		&i.OrganizationID,
	)
	return i, err
}

const revokeMCPOAuthGrantTokens = `-- name: RevokeMCPOAuthGrantTokens :exec
WITH codes AS (
    DELETE FROM mcp_oauth_codes WHERE mcp_oauth_codes.grant_id = $1 AND used_at IS NULL
)
UPDATE mcp_oauth_tokens SET revoked_at = NOW()
WHERE mcp_oauth_tokens.grant_id = $1 AND revoked_at IS NULL
`

// Every token family of a grant; unused codes of the grant go too.
func (q *Queries) RevokeMCPOAuthGrantTokens(ctx context.Context, grantID int64) error {
	_, err := q.db.Exec(ctx, revokeMCPOAuthGrantTokens, grantID)
	return err
}

const revokeMCPOAuthToken = `-- name: RevokeMCPOAuthToken :execrows
UPDATE mcp_oauth_tokens SET revoked_at = NOW() WHERE id = $1 AND revoked_at IS NULL
`

// Revoking is the claim: of two concurrent refreshes only one wins.
func (q *Queries) RevokeMCPOAuthToken(ctx context.Context, id int64) (int64, error) {
	result, err := q.db.Exec(ctx, revokeMCPOAuthToken, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

